                                onUpdate={(name) => patch({name})}
                                placeholder="Ваше имя"
                                hasClear
                            />
                        </Field>

                        <Field label="Email">
                            <TextInput
                                type="email"
                                value={form.email}
                                onUpdate={(email) => patch({email})}
                                placeholder="you@example.com"
                                hasClear
                            />
                        </Field>

                        <Divider />

                        {/* Локализация */}
                        <Field label="Язык интерфейса">
                            <Select
                                value={[form.language]}
                                onUpdate={([language]) => patch({language})}
                                options={LANGUAGES}
                                width="max"
                            />
                        </Field>

                        <Field label="Часовой пояс">
                            <Select
                                value={[form.timezone]}
                                onUpdate={([timezone]) => patch({timezone})}
                                options={TIMEZONES}
                                width="max"
                            />
                        </Field>

                        <Divider />

                        {/* Безопасность */}
                        <Field label="Безопасность">
                            <Switch
                                checked={form.twoFactor}
                                onUpdate={(twoFactor) => patch({twoFactor})}
                            >
                                Двухфакторная авторизация
                            </Switch>
                        </Field>

                        {/* Уведомления */}
                        <Field label="Email-уведомления">
                            <Flex direction="column" gap={2}>
                                <Checkbox
                                    checked={form.notifications.productNews}
                                    onUpdate={(checked) =>
                                        patch({
                                            notifications: {
                                                ...form.notifications,
                                                productNews: checked,
                                            },
                                        })
                                    }
                                >
                                    Новости продукта
                                </Checkbox>
                                <Checkbox
                                    checked={form.notifications.systemAlerts}
                                    onUpdate={(checked) =>
                                        patch({
                                            notifications: {
                                                ...form.notifications,
                                                systemAlerts: checked,
                                            },
                                        })
                                    }
                                >
                                    Системные алерты
                                </Checkbox>
                                <Checkbox
                                    checked={form.notifications.weeklyDigest}
                                    onUpdate={(checked) =>
                                        patch({
                                            notifications: {
                                                ...form.notifications,
                                                weeklyDigest: checked,
                                            },
                                        })
                                    }
                                >
                                    Дайджест за неделю
                                </Checkbox>
                            </Flex>
                        </Field>
                    </Flex>
                </Card>

                {/* Действия */}
                <Flex alignItems="center" gap={3}>
                    <Button view="action" size="l" onClick={handleSave}>
                        Сохранить
                    </Button>
                    <Button view="flat" size="l" onClick={handleCancel}>
                        Отмена
                    </Button>
                    {showSaved ? (
                        <Text variant="body-2" color="positive" style={{flexShrink: 0}}>
                            Изменения сохранены
                        </Text>
                    ) : null}
                </Flex>
            </Flex>
        </Box>
    );
}
